        onClick={onRetry}
        style={{
          marginTop: 12,
          padding: '6px 12px',
          fontSize: 13,
          backgroundColor: 'var(--bg-hover)',
          border: '1px solid var(--border-light)',
          borderRadius: 'var(--radius-sm)',
          color: 'var(--text-primary)',
          cursor: 'pointer',
        }}
      >
        Retry
      </button>
    </div>
  );
}

