function PrimaryButton({
  onClick,
  children,
}: {
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 6,
        padding: '8px 14px',
        fontSize: 13,
        fontWeight: 500,
        color: 'var(--text-inverse)',
        backgroundColor: 'var(--accent)',
        border: 'none',
        borderRadius: 'var(--radius-sm)',
        cursor: 'pointer',
