      onMouseOver={(e) => (e.currentTarget.style.backgroundColor = 'var(--accent-hover)')}
      onMouseOut={(e) => (e.currentTarget.style.backgroundColor = 'var(--accent)')}
    >
      {children}
    </button>
  );
}

