      <Chip label={`All categories`} active={active === 'all'} onClick={() => onSelect('all')} />
      {categories.map(([cat, count]) => (
        <Chip
          key={cat}
          label={`${cat} · ${count}`}
          active={active === cat}
          onClick={() => onSelect(cat)}
