export default function ToolConfigPage() {
  const params = useParams();
  const router = useRouter();
  const slug = params.slug as string;
  const config = TOOL_CONFIGS[slug];

  const [connected, setConnected] = useState(false);
  const [fieldValues, setFieldValues] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);

  if (!config) {
    return (
      <div style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto' }}>
        <div style={{ textAlign: 'center', padding: '48px', color: 'var(--text-secondary)' }}>
          <div style={{ fontSize: '48px', marginBottom: '16px', opacity: 0.4 }}>?</div>
          <h2 style={{ fontSize: '20px', fontWeight: 600, marginBottom: '8px', color: 'var(--text-primary)' }}>Tool not found</h2>
          <p style={{ marginBottom: '24px' }}>The tool &quot;{slug}&quot; doesn&apos;t exist or isn&apos;t available yet.</p>
          <button
            onClick={() => router.push('/tools')}
            style={{
              padding: '10px 20px',
              backgroundColor: 'var(--accent)',
              color: 'white',
              border: 'none',
              borderRadius: 'var(--radius-md)',
              fontSize: '14px',
              fontWeight: 500,
              cursor: 'pointer',
            }}
          >
            Back to Tools
          </button>
        </div>
      </div>
    );
  }

  // Route to specialized components for tools with real API integration
  if (slug === 'github') return <GitHubToolConfig config={config} router={router} />;
  if (slug === 'tavily') return <TavilyToolConfig config={config} router={router} />;

  const handleConnect = () => {
    setConnected(true);
  };

  const handleSave = async () => {
    setIsSaving(true);
    // Simulate API call
    await new Promise((r) => setTimeout(r, 800));
    setIsSaving(false);
  };

  const handleDisconnect = () => {
    setConnected(false);
    setFieldValues({});
  };

  return (
    <div style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto' }}>
      <ToolBackLink router={router} />
      <ToolHeader config={config} connected={connected} />

      {!connected ? (
        <ToolConnectPrompt config={config} onConnect={handleConnect} />
      ) : (
        <>
          {/* Connection status bar */}
          <div style={{ padding: '14px 16px', backgroundColor: 'var(--bg-secondary)', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-light)', marginBottom: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#22c55e' }} />
              <span style={{ fontSize: '14px' }}>Connected to {config.name}</span>
            </div>
            <button onClick={handleDisconnect} style={{ padding: '6px 14px', backgroundColor: 'transparent', border: '1px solid var(--border-light)', borderRadius: 'var(--radius-md)', color: 'var(--text-secondary)', fontSize: '13px', cursor: 'pointer' }}>
              Disconnect
            </button>
          </div>

          {/* Configuration fields */}
          <div style={{ backgroundColor: 'var(--bg-secondary)', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-light)', padding: '24px', marginBottom: '24px' }}>
            <h3 style={{ margin: '0 0 20px', fontSize: '16px', fontWeight: 600 }}>Configuration</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '18px' }}>
              {config.fields.map((field) => (
                <div key={field.key}>
                  <label style={{ display: 'block', fontSize: '13px', fontWeight: 500, marginBottom: '6px', color: 'var(--text-primary)' }}>
                    {field.label}
                  </label>
                  {field.description && (
                    <div style={{ fontSize: '12px', color: 'var(--text-tertiary)', marginBottom: '6px' }}>
                      {field.description}
                    </div>
                  )}
                  {field.type === 'textarea' ? (
                    <textarea
                      value={fieldValues[field.key] || ''}
                      onChange={(e) => setFieldValues((prev) => ({ ...prev, [field.key]: e.target.value }))}
                      placeholder={field.placeholder}
                      rows={4}
                      style={{ width: '100%', padding: '10px 12px', backgroundColor: 'var(--bg-primary)', border: '1px solid var(--border-light)', borderRadius: 'var(--radius-md)', color: 'var(--text-primary)', fontSize: '13px', outline: 'none', resize: 'vertical', fontFamily: "'SF Mono', 'Fira Code', Consolas, monospace" }}
                    />
                  ) : (
                    <input
                      type={field.type || 'text'}
                      value={fieldValues[field.key] || ''}
                      onChange={(e) => setFieldValues((prev) => ({ ...prev, [field.key]: e.target.value }))}
                      placeholder={field.placeholder}
                      style={{ width: '100%', padding: '10px 12px', backgroundColor: 'var(--bg-primary)', border: '1px solid var(--border-light)', borderRadius: 'var(--radius-md)', color: 'var(--text-primary)', fontSize: '13px', outline: 'none' }}
                    />
                  )}
                </div>
              ))}
            </div>
            <div style={{ marginTop: '24px', display: 'flex', gap: '12px' }}>
              <button onClick={handleSave} disabled={isSaving} style={{ padding: '10px 24px', backgroundColor: config.color, color: 'white', border: 'none', borderRadius: 'var(--radius-md)', fontSize: '14px', fontWeight: 500, cursor: isSaving ? 'not-allowed' : 'pointer', opacity: isSaving ? 0.7 : 1 }}>
                {isSaving ? 'Saving...' : 'Save Configuration'}
              </button>
              <button onClick={() => router.push('/tools')} style={{ padding: '10px 24px', backgroundColor: 'transparent', border: '1px solid var(--border-light)', borderRadius: 'var(--radius-md)', color: 'var(--text-primary)', fontSize: '14px', cursor: 'pointer' }}>
                Cancel
              </button>
            </div>
          </div>

          <ToolFeatures config={config} />
        </>
      )}
    </div>
  );
}

/**
 * V Core Page
 * 
 * Complete V Core dashboard with all modules:
 * - Control Plane
 * - Business Core
 * - Workflow Engine
 * - Mission Control
 */

'use client';

import React, { useState, useEffect } from 'react';
import { useVCore } from '../../hooks/useVCore';
import {
  OrganizationCard,
  MemberList,
  InviteModal,
  EntityCard,
  RecordTable,
  RecordForm,
  WorkflowCard,
  ExecutionList,
  MissionControlDashboard,
} from '../../components/v-core';

type Tab = 'dashboard' | 'control-plane' | 'business-core' | 'workflows' | 'dev-guide';

export default function VCorePage() {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [selectedEntity, setSelectedEntity] = useState<string | null>(null);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [showRecordForm, setShowRecordForm] = useState(false);

  const {
    isLoading,
    error,
    // Control Plane
    organizations,
    currentOrg,
    members,
    roles,
    loadOrganizations,
    loadMembers,
    inviteMember,
    // Business Core
    entities,
    records,
    loadEntities,
    loadRecords,
    createRecord,
    deleteRecord,
    // Workflows
    workflows,
    executions,
    loadWorkflows,
    loadExecutions,
    activateWorkflow,
    pauseWorkflow,
    executeWorkflow,
    // Mission Control
    dashboard,
    loadDashboard,
    approveRequest,
    rejectRequest,
    resolveAlert,
  } = useVCore();

  // Load initial data
  useEffect(() => {
    loadOrganizations();
    loadEntities();
    loadWorkflows();
    loadDashboard();
  }, []);

  useEffect(() => {
    if (currentOrg) {
      loadMembers(currentOrg.id);
    }
  }, [currentOrg]);

  useEffect(() => {
    if (selectedEntity) {
      loadRecords(selectedEntity);
    }
  }, [selectedEntity]);

  const selectedEntityData = entities.find(e => e.id === selectedEntity);

  const tabs: { id: Tab; label: string; icon: string }[] = [
    { id: 'dashboard', label: 'Mission Control', icon: '🎛️' },
    { id: 'control-plane', label: 'Control Plane', icon: '👥' },
    { id: 'business-core', label: 'Business Core', icon: '📊' },
    { id: 'workflows', label: 'Workflows', icon: '⚡' },
    { id: 'dev-guide', label: 'Dev Guide', icon: '📖' },
  ];

  return (
    <div style={{ minHeight: '100vh', background: 'var(--color-background-secondary, #f5f5f7)' }}>
      {/* Header */}
      <header
        style={{
          background: 'white',
          borderBottom: '1px solid var(--color-border, #e5e5ea)',
          padding: '1rem 2rem',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <h1 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 600 }}>
            <span style={{ background: 'linear-gradient(135deg, #007AFF, #5856D6)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              V Core
            </span>
          </h1>
          <span style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary, #6e6e73)' }}>
            The Brain
          </span>
        </div>

        {/* Tab Navigation */}
        <nav style={{ display: 'flex', gap: '0.5rem' }}>
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              style={{
                padding: '0.625rem 1rem',
                background: activeTab === tab.id ? 'var(--color-accent, #007AFF)' : 'transparent',
                color: activeTab === tab.id ? 'white' : 'var(--color-text-secondary, #6e6e73)',
                border: 'none',
                borderRadius: '8px',
                fontSize: '0.875rem',
                fontWeight: 500,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem',
                transition: 'all 0.2s',
              }}
            >
              <span>{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </nav>

        {currentOrg && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <div
              style={{
                width: '32px',
                height: '32px',
                borderRadius: '8px',
                background: 'linear-gradient(135deg, #007AFF, #5856D6)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: 'white',
                fontWeight: 600,
                fontSize: '0.875rem',
              }}
            >
              {currentOrg.name.charAt(0)}
            </div>
            <span style={{ fontSize: '0.875rem', fontWeight: 500 }}>{currentOrg.name}</span>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main style={{ padding: '2rem', maxWidth: '1400px', margin: '0 auto' }}>
        {isLoading && (
          <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--color-text-secondary, #6e6e73)' }}>
            Loading...
          </div>
        )}

        {error && (
          <div style={{ padding: '1rem', background: '#fee2e2', color: '#dc2626', borderRadius: '8px', marginBottom: '1rem' }}>
            {error}
          </div>
        )}

        {/* Mission Control Tab */}
        {activeTab === 'dashboard' && dashboard && (
          <MissionControlDashboard
            data={dashboard}
            onApprove={approveRequest}
            onReject={rejectRequest}
            onResolveAlert={resolveAlert}
          />
        )}

        {/* Control Plane Tab */}
        {activeTab === 'control-plane' && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem' }}>
            {/* Organizations */}
            <div>
              <h2 style={{ margin: '0 0 1rem', fontSize: '1.25rem', fontWeight: 600 }}>🏢 Organizations</h2>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {organizations.map((org) => (
                  <OrganizationCard
                    key={org.id}
                    org={org}
                    isSelected={currentOrg?.id === org.id}
                  />
                ))}
              </div>
            </div>

            {/* Team Members */}
            <div>
              <MemberList members={members} onInvite={() => setShowInviteModal(true)} />
            </div>
          </div>
        )}

        {/* Business Core Tab */}
        {activeTab === 'business-core' && (
          <div style={{ display: 'grid', gridTemplateColumns: selectedEntity ? '300px 1fr' : '1fr', gap: '2rem' }}>
            {/* Entity List */}
            <div>
              <h2 style={{ margin: '0 0 1rem', fontSize: '1.25rem', fontWeight: 600 }}>📋 Entities</h2>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {entities.map((entity) => (
                  <EntityCard
                    key={entity.id}
                    entity={entity}
                    onClick={() => setSelectedEntity(entity.id)}
                  />
                ))}
              </div>
            </div>

            {/* Records View */}
            {selectedEntity && selectedEntityData && (
              <div style={{ background: 'white', borderRadius: '12px', border: '1px solid var(--color-border, #e5e5ea)', overflow: 'hidden' }}>
                <div style={{ padding: '1rem 1.5rem', borderBottom: '1px solid var(--color-border, #e5e5ea)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                    <span style={{ fontSize: '1.5rem' }}>{selectedEntityData.icon}</span>
                    <div>
                      <h3 style={{ margin: 0, fontSize: '1.125rem', fontWeight: 600 }}>{selectedEntityData.labelPlural}</h3>
                      <span style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6e6e73)' }}>
                        {records.length} records
                      </span>
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button
                      onClick={() => setShowRecordForm(true)}
                      style={{
                        padding: '0.5rem 1rem',
                        background: 'var(--color-accent, #007AFF)',
                        color: 'white',
                        border: 'none',
                        borderRadius: '8px',
                        fontSize: '0.875rem',
                        fontWeight: 500,
                        cursor: 'pointer',
                      }}
                    >
                      + New {selectedEntityData.label}
