// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 VOS3 Project
//
// P5.5 — Sandboxed App File Explorer.
//
// Renders the contents of an app's isolated storage directory
// (`{app_data_dir}/apps/{app_id}/storage/`) as a flat list with
// folder/file icons + size + last-modified columns.
//
// Authentication: the dashboard's parent operator session is the
// outer gate; this component additionally sends the app's
// X-App-Id + X-App-Secret headers because /api/apps/{id}/fs/list
// runs under `get_app_context` (P4.2). The component takes these
// in via props rather than fetching the secret itself — secrets
// are write-once and live only in the install response.
//
// Behavior:
//   * Loads on mount + refreshes when `appId` / `secret` change.
//   * Click a folder row to descend; click ".." to ascend.
//   * 403 / 404 / network errors render an inline banner without
//     blowing away the previous listing.

'use client';

import type React from 'react';
import { useCallback, useEffect, useMemo, useState } from 'react';

interface FsEntry {
  name: string;
  path: string;
  is_dir: boolean;
  size_bytes: number | null;
  modified_at_ms: number | null;
}

interface FsListResponse {
  app_id: string;
  path: string;
  recursive: boolean;
  count: number;
  entries: FsEntry[];
}

interface AppFileExplorerProps {
  appId: string;
  /** Plain-text app secret (from install response). When null/empty
   *  the component renders a stub — the secret is the runtime
   *  authentication for the /fs/list endpoint. */
  secret: string | null;
  /** Optional backend origin. Defaults to relative paths. */
  apiOrigin?: string;
  /** Triggered whenever a file write/upload changes the listing. */
  refreshToken?: number;
}

function formatSize(n: number | null): string {
  if (n === null) return '—';
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function formatMtime(ms: number | null): string {
  if (!ms) return '—';
  try {
    return new Date(ms).toLocaleString();
  } catch {
    return '—';
  }
}

function FileIcon({ entry }: { entry: FsEntry }): React.ReactElement {
  // Folder → blue chevron-ish square. File → ext-keyed glyph.
  // Avoid any dependency on a heavy icon set — these are inline SVG.
  if (entry.is_dir) {
    return (
      <span
        aria-hidden
        className="inline-flex h-5 w-5 items-center justify-center rounded-sm border border-indigo-500/40 bg-indigo-500/20 text-[10px] font-semibold text-indigo-200"
      >
        DIR
      </span>
    );
  }
  const ext = entry.name.split('.').pop()?.toLowerCase() ?? '';
  const palette: Record<string, string> = {
    txt: 'border-slate-500/40 bg-slate-500/15 text-slate-200',
    md: 'border-emerald-500/40 bg-emerald-500/15 text-emerald-200',
    json: 'border-amber-500/40 bg-amber-500/15 text-amber-200',
    yml: 'border-amber-500/40 bg-amber-500/15 text-amber-200',
    yaml: 'border-amber-500/40 bg-amber-500/15 text-amber-200',
    py: 'border-sky-500/40 bg-sky-500/15 text-sky-200',
    js: 'border-yellow-500/40 bg-yellow-500/15 text-yellow-200',
    ts: 'border-blue-500/40 bg-blue-500/15 text-blue-200',
    log: 'border-rose-500/40 bg-rose-500/15 text-rose-200',
  };
  const cls = palette[ext] ?? 'border-slate-600 bg-slate-700/30 text-slate-300';
  return (
    <span
      aria-hidden
      className={`inline-flex h-5 w-9 items-center justify-center rounded-sm border text-[10px] font-mono uppercase ${cls}`}
    >
      {ext || 'file'}
    </span>
  );
}

export function AppFileExplorer({
  appId,
  secret,
  apiOrigin = '',
  refreshToken = 0,
}: AppFileExplorerProps): React.ReactElement {
  const [cwd, setCwd] = useState('');                  // relative to sandbox
  const [entries, setEntries] = useState<FsEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const headers = useMemo(
    () => ({
      'X-App-Id': appId,
      'X-App-Secret': secret ?? '',
    }),
    [appId, secret],
  );

  const fetchListing = useCallback(async () => {
    if (!secret) {
      setError('App secret missing — cannot authenticate to /fs/list');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const url = `${apiOrigin}/api/apps/${appId}/fs/list?path=${encodeURIComponent(cwd)}`;
      const res = await fetch(url, { headers });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        const code = body?.detail?.error ?? res.status;
        throw new Error(`list failed: ${code}`);
      }
      const body = (await res.json()) as FsListResponse;
      setEntries(body.entries);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'list failed');
    } finally {
      setLoading(false);
    }
  }, [apiOrigin, appId, cwd, headers, secret]);

  useEffect(() => {
    fetchListing();
  }, [fetchListing, refreshToken]);

  const onFolderEnter = useCallback((entry: FsEntry) => {
    setCwd(entry.path);
  }, []);

  const onAscend = useCallback(() => {
    if (!cwd) return;
    const parts = cwd.split('/');
    parts.pop();
    setCwd(parts.join('/'));
  }, [cwd]);

  return (
    <div className="rounded-lg border border-slate-800 bg-slate-900/30">
      <div className="flex items-center justify-between border-b border-slate-800 px-4 py-2 text-xs text-slate-300">
        <div className="flex items-center gap-2">
          <span className="font-semibold text-slate-200">Storage</span>
          <span className="font-mono text-slate-500">
            /{cwd || ''}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {cwd ? (
            <button
              type="button"
              onClick={onAscend}
              className="rounded border border-slate-700 px-2 py-0.5 hover:bg-slate-800"
            >
              ↑ up
            </button>
          ) : null}
          <button
            type="button"
            onClick={fetchListing}
            className="rounded border border-slate-700 px-2 py-0.5 hover:bg-slate-800"
          >
            Refresh
          </button>
        </div>
      </div>

      {error ? (
        <div className="border-b border-slate-800 bg-red-500/10 px-4 py-2 text-xs text-red-200">
          {error}
        </div>
      ) : null}

      <ul className="max-h-72 overflow-y-auto text-sm">
        {loading && entries.length === 0 ? (
          <li className="px-4 py-3 text-xs text-slate-500">loading…</li>
        ) : null}
        {entries.length === 0 && !loading ? (
          <li className="px-4 py-6 text-center text-xs text-slate-500">
            empty
          </li>
        ) : null}
        {entries.map((entry) => (
          <li
            key={entry.path}
            className="grid grid-cols-[28px_1fr_80px_140px] items-center gap-3 border-b border-slate-800/50 px-4 py-2 last:border-b-0 hover:bg-slate-800/40"
          >
            <FileIcon entry={entry} />
            {entry.is_dir ? (
              <button
                type="button"
                onClick={() => onFolderEnter(entry)}
                className="truncate text-left text-slate-100 hover:text-indigo-200"
              >
                {entry.name}/
              </button>
            ) : (
              <span className="truncate text-slate-200">{entry.name}</span>
            )}
            <span className="text-right font-mono text-xs text-slate-500">
              {formatSize(entry.size_bytes)}
            </span>
            <span className="text-right text-xs text-slate-500">
              {formatMtime(entry.modified_at_ms)}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 VOS3 Project
//
// P5.5 — Sandboxed app file uploader.
//
// Drag-and-drop area that uploads the dropped file's contents
// through POST /api/apps/{id}/fs/write. Authenticates with the
// app's X-App-Id + X-App-Secret headers (same pattern as the
// explorer).
//
// Behavior:
//   * Accepts a single file at a time. Multi-file uploads queue
//     sequentially so a failure on file N doesn't poison file N+1.
//   * Reads as UTF-8 text (sufficient for the directive's POST
//     /fs/write contract, which is JSON-encoded). Binary support
//     lands in a future P5.x via the /state/file endpoint shape
//     once that endpoint accepts base64.
//   * Real-time feedback per upload:
//       green check on success
//       amber warning when the route returns 403 / scope_violation
//       red error on network / 500 failures
//   * Calls `onUploaded()` after each successful write so the
//     explorer can refresh.

'use client';

import type React from 'react';
import {
  type DragEvent,
  useCallback,
  useMemo,
  useRef,
  useState,
} from 'react';

interface UploadEvent {
  id: string;
  filename: string;
  size_bytes: number;
  status: 'pending' | 'success' | 'denied' | 'error';
  message?: string;
}

interface AppFileUploadZoneProps {
  appId: string;
  secret: string | null;
  apiOrigin?: string;
  /** Fires after every successful write — the explorer should
   *  re-list. */
  onUploaded?: () => void;
}

export function AppFileUploadZone({
  appId,
  secret,
  apiOrigin = '',
  onUploaded,
}: AppFileUploadZoneProps): React.ReactElement {
  const [events, setEvents] = useState<UploadEvent[]>([]);
  const [dragging, setDragging] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const headers = useMemo(
    () => ({
      'X-App-Id': appId,
      'X-App-Secret': secret ?? '',
      'Content-Type': 'application/json',
    }),
    [appId, secret],
  );

  const uploadOne = useCallback(
    async (file: File) => {
      const eventId = `${file.name}-${Date.now()}-${Math.random()}`;
      const seed: UploadEvent = {
        id: eventId,
        filename: file.name,
        size_bytes: file.size,
        status: 'pending',
      };
      setEvents((prev) => [seed, ...prev].slice(0, 8));
      try {
        const text = await file.text();
        const url = `${apiOrigin}/api/apps/${appId}/fs/write`;
        const res = await fetch(url, {
          method: 'POST',
          headers,
          body: JSON.stringify({ path: file.name, content: text }),
        });
        if (res.ok) {
          setEvents((prev) =>
            prev.map((e) =>
              e.id === eventId
                ? { ...e, status: 'success', message: 'written' }
                : e,
            ),
          );
          onUploaded?.();
          return;
        }
        const body = await res.json().catch(() => ({}));
        const detail = body?.detail ?? {};
        if (
          res.status === 403
          && (detail.scope === 'filesystem.write'
              || detail.error === 'scope_violation'
              || detail.error === 'path_traversal_attempt')
        ) {
          setEvents((prev) =>
            prev.map((e) =>
              e.id === eventId
                ? {
                    ...e,
                    status: 'denied',
                    message:
                      detail.error === 'path_traversal_attempt'
                        ? 'path traversal blocked — app auto-isolated'
                        : 'filesystem.write denied by manifest',
                  }
                : e,
            ),
          );
          return;
        }
        setEvents((prev) =>
          prev.map((e) =>
            e.id === eventId
              ? {
                  ...e,
                  status: 'error',
                  message: `HTTP ${res.status} ${detail.error ?? ''}`,
                }
              : e,
          ),
        );
      } catch (err) {
        setEvents((prev) =>
          prev.map((e) =>
            e.id === eventId
              ? {
                  ...e,
                  status: 'error',
                  message:
                    err instanceof Error ? err.message : 'upload failed',
                }
              : e,
          ),
        );
      }
    },
    [apiOrigin, appId, headers, onUploaded],
  );

  const handleFiles = useCallback(
    async (files: FileList | null) => {
      if (!files || files.length === 0) return;
      // Sequential to keep per-file events ordered + bounded.
      for (let i = 0; i < files.length; i += 1) {
        // eslint-disable-next-line no-await-in-loop
        await uploadOne(files[i]);
      }
    },
    [uploadOne],
  );

  const onDrop = useCallback(
    (e: DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      setDragging(false);
      void handleFiles(e.dataTransfer?.files ?? null);
    },
    [handleFiles],
  );

  const onDragOver = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragging(true);
  }, []);

  const onDragLeave = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragging(false);
  }, []);

  return (
    <div className="space-y-3">
      <div
        onDrop={onDrop}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onClick={() => inputRef.current?.click()}
        className={`flex cursor-pointer items-center justify-center rounded-lg border-2 border-dashed px-4 py-8 text-sm transition ${
          dragging
            ? 'border-indigo-400 bg-indigo-500/10 text-indigo-100'
            : 'border-slate-700 bg-slate-900/40 text-slate-400 hover:border-slate-500'
        }`}
        role="button"
        aria-label="Drag files here to upload"
        tabIndex={0}
      >
        <input
          ref={inputRef}
          type="file"
          multiple
          className="hidden"
          onChange={(e) => {
            void handleFiles(e.target.files);
            // Reset so the same file can be re-uploaded.
            e.target.value = '';
          }}
        />
        {dragging ? 'Drop to upload' : 'Drag a file here, or click to select'}
      </div>

      {events.length > 0 ? (
        <ul className="space-y-1">
          {events.map((e) => {
            const palette: Record<UploadEvent['status'], string> = {
              pending: 'border-slate-700 bg-slate-800/50 text-slate-300',
              success: 'border-emerald-500/40 bg-emerald-500/10 text-emerald-200',
              denied: 'border-amber-500/40 bg-amber-500/10 text-amber-200',
              error: 'border-red-500/40 bg-red-500/10 text-red-200',
            };
            const icon: Record<UploadEvent['status'], string> = {
              pending: '⏳',
              success: '✓',
              denied: '⚠️',
              error: '✗',
            };
            return (
              <li
                key={e.id}
                className={`flex items-center justify-between rounded-md border px-3 py-1.5 text-xs ${palette[e.status]}`}
              >
                <div className="flex items-center gap-2">
                  <span>{icon[e.status]}</span>
                  <span className="truncate">{e.filename}</span>
                  <span className="text-slate-500">
                    ({e.size_bytes} B)
                  </span>
                </div>
                <span className="truncate text-right text-[11px] opacity-80">
                  {e.message ?? e.status}
                </span>
              </li>
            );
          })}
        </ul>
      ) : null}
    </div>
  );
}

