    low: { bg: '#f3f4f6', text: '#6b7280' },
    normal: { bg: '#dbeafe', text: '#2563eb' },
    high: { bg: '#fef3c7', text: '#d97706' },
    urgent: { bg: '#fee2e2', text: '#dc2626' },
